#include "scenario/scenario.hpp"
#include <iostream>
#include <string>
#include <vector>
#include <cmath>
#include <iomanip>
#include <sstream>
#include <random>
#include <algorithm>
#include <limits>
static std::string html_escape(const std::string& s){std::string r;for(char c:s){if(c=='&')r+="&amp;";else if(c=='<')r+="&lt;";else if(c=='>')r+="&gt;";else if(c=='\"')r+="&quot;";else r+=c;}return r;}
int main(int argc,char**argv){if(argc<2||std::string(argv[1])=="--help"||std::string(argv[1])=="-h"){std::cout<<"scenario-calculator <run|compare|diff|html|monte-carlo|cohort|seek|breakeven|sensitivity|check> <scenario.ini> [--currency CODE] [--format text|csv|markdown|json]\nAll results are HYPOTHETICAL / NOT A FORECAST.\n";return argc<2?1:0;}std::string cmd=argv[1],format="text",currency; if(cmd!="run"&&cmd!="compare"&&cmd!="diff"&&cmd!="html"&&cmd!="monte-carlo"&&cmd!="cohort"&&cmd!="seek"&&cmd!="breakeven"&&cmd!="sensitivity"&&cmd!="check"){std::cerr<<"Unknown command: "<<cmd<<"\n";return 2;}if(argc<3){std::cerr<<"A scenario file is required\n";return 2;}std::vector<std::string> files;for(int i=2;i<argc;++i){std::string a=argv[i];if(a=="--format"&&i+1<argc)format=argv[++i];else if(a=="--currency"&&i+1<argc)currency=argv[++i];else if(a.rfind("--",0)==0){std::cerr<<"Unknown flag or missing flag value: "<<a<<"\n";return 2;}else files.push_back(a);}try{if(!currency.empty()&&currency.size()!=3)throw std::runtime_error("--currency must be a three-letter ISO currency code");if(cmd=="compare"||cmd=="diff"){if(files.size()!=2){std::cerr<<cmd<<" requires exactly two scenario files\n";return 2;}auto a=scenario::load(files[0]),b=scenario::load(files[1]);auto check=[](const scenario::Model&m){auto e=scenario::validate(m);if(!e.empty())throw std::runtime_error("invalid scenario: "+e.front());};check(a);check(b);if(a.currency!=b.currency)throw std::runtime_error("refusing to compare scenarios with different currencies ("+a.currency+" and "+b.currency+")");if(!currency.empty()&&(a.currency!=currency||b.currency!=currency))throw std::runtime_error("scenario currency does not match --currency "+currency);if(cmd=="compare"){std::cout<<"HYPOTHETICAL / NOT A FORECAST — scenario comparison\n";for(const auto&m:{a,b}){double normalized=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);std::cout<<std::left<<std::setw(30)<<m.name<<" currency="<<m.currency<<" monthly_price="<<(m.has_price?m.currency+" "+std::to_string(normalized):"unavailable")<<" target_payers="<<(m.has_price?std::to_string(static_cast<long long>(std::ceil(m.target/normalized))):"unavailable")<<" replacements="<<(m.has_price&&m.has_loss?std::to_string(static_cast<long long>(std::ceil(m.target/normalized*m.loss))):"unavailable")<<"\n";}}else{std::cout<<"HYPOTHETICAL / NOT A FORECAST — scenario differences\n";auto d=[&](const std::string&k,const std::string&x,const std::string&y){if(x!=y)std::cout<<k<<": "<<a.name<<"="<<x<<"; "<<b.name<<"="<<y<<"\n";};d("target_mrr",std::to_string(a.target),std::to_string(b.target));d("price",a.has_price?std::to_string(a.price):"unavailable",b.has_price?std::to_string(b.price):"unavailable");d("period",a.period,b.period);d("expiry_loss",a.has_loss?std::to_string(a.loss):"unavailable",b.has_loss?std::to_string(b.loss):"unavailable");d("first_open_to_activation",a.has_activation?std::to_string(a.open_activation):"unavailable",b.has_activation?std::to_string(b.open_activation):"unavailable");d("activation_to_paid",a.has_activation?std::to_string(a.activation_paid):"unavailable",b.has_activation?std::to_string(b.activation_paid):"unavailable");auto outputs=[](const scenario::Model&m){double rate=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);long long n=m.has_price?static_cast<long long>(std::ceil(m.target/rate)):0;return std::pair<std::string,std::string>{m.has_price?std::to_string(n):"unavailable",m.has_price&&m.has_loss?std::to_string(static_cast<long long>(std::ceil(n*m.loss))):"unavailable"};};auto x=outputs(a),y=outputs(b);d("output.active_payers",x.first,y.first);d("output.monthly_replacements",x.second,y.second);}return 0;}if(files.size()!=1){std::cerr<<cmd<<" requires exactly one scenario file\n";return 2;}auto m=scenario::load(files.front());if(!currency.empty()&&m.currency!=currency)throw std::runtime_error("scenario currency "+m.currency+" does not match --currency "+currency);if(cmd=="monte-carlo"){auto issues=scenario::validate(m);if(!issues.empty())throw std::runtime_error("invalid scenario: "+issues.front());if(!m.has_price||!m.has_expiry_range||!m.has_activation_range||!m.has_paid_range)throw std::runtime_error("monte-carlo requires price and expiry_loss_min/max, activation_min/max, paid_min/max ranges");double monthly=m.price*(m.period=="weekly"?52.0/12:m.period=="quarterly"?1.0/3:m.period=="annual"?1.0/12:1);double payers=std::ceil(m.target/monthly);std::mt19937 rng(m.seed);std::uniform_real_distribution<double> el(m.expiry_low,m.expiry_high),al(m.activation_low,m.activation_high),pl(m.paid_low,m.paid_high);std::vector<double> replacement,opens;replacement.reserve(m.iterations);opens.reserve(m.iterations);for(int i=0;i<m.iterations;++i){double loss=el(rng),activation=al(rng),paid=pl(rng);replacement.push_back(payers*loss);opens.push_back(activation*paid>0?payers/(activation*paid):std::numeric_limits<double>::infinity());}auto percentile=[](std::vector<double>&v,double p){std::sort(v.begin(),v.end());return v[static_cast<std::size_t>(std::ceil(p*(v.size()-1)))];};std::cout<<"HYPOTHETICAL / NOT A FORECAST — Monte Carlo assumption sampling\nseed="<<m.seed<<" iterations="<<m.iterations<<"\n";for(double p:{0.05,0.5,0.95}){auto r=percentile(replacement,p),o=percentile(opens,p);std::cout<<static_cast<int>(p*100)<<"th percentile replacements="<<std::ceil(r)<<"; first opens="<<(std::isfinite(o)?std::to_string(static_cast<long long>(std::ceil(o))):"unavailable (sampled conversion probability is zero)")<<"\n";}return 0;}if(cmd=="html"){const auto report=scenario::execute(m,"run");std::cout<<"<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>HYPOTHETICAL — "<<html_escape(m.name)<<"</title><style>body{font:16px system-ui;max-width:900px;margin:3rem auto;padding:0 1rem;color:#222}h1{color:#8b1e1e}.warning{border:2px solid #b00;padding:1rem;font-weight:bold}pre{white-space:pre-wrap;background:#f4f4f4;padding:1rem;overflow:auto}</style><h1>HYPOTHETICAL / NOT A FORECAST</h1><p class=\"warning\">Synthetic decision-preparation scenario only. Not approved pricing, live data, a forecast, or campaign authorization.</p><h2>"<<html_escape(m.name)<<"</h2><pre>"<<html_escape(report)<<"</pre></html>\n";}else std::cout<<scenario::execute(m,cmd,format);}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
